<?php
declare(strict_types=1);
$private=sys_get_temp_dir().'/ectro-address-'.bin2hex(random_bytes(6));mkdir($private,0700);putenv('APP_DATA_DIR='.$private);putenv('APP_ENV=development');putenv('APP_KEY='.base64_encode(random_bytes(32)));
register_shutdown_function(function()use($private){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($private,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $file)$file->isDir()?rmdir($file->getPathname()):unlink($file->getPathname());rmdir($private);});
require __DIR__.'/../app/bootstrap.php';
$checks=0;function addressCheck(bool $condition,string $why):void{global $checks;if(!$condition)throw new RuntimeException($why);$checks++;}
function addressGroup(string $uid,string $name,string $mode='formal',array $periods=[]):string{$gid=id();query('INSERT INTO groups VALUES(?,?,?,?,?)',[$gid,$name,'','{}',now()]);query('INSERT INTO group_members VALUES(?,?)',[$gid,$uid]);saveGroupAddress($gid,$mode);if($periods)saveGroupPeriods($gid,groupPeriodsInput($periods));return $gid;}
$uid=id();query('INSERT INTO users(id,name,email,password,role,created_at) VALUES(?,?,?,?,?,?)',[$uid,'Address test','address@example.test','unused','user',now()]);$u=one('SELECT * FROM users WHERE id=?',[$uid]);
$at=(new DateTimeImmutable('2026-11-07 12:00:00',new DateTimeZone(GROUP_PERIOD_ZONE)))->getTimestamp();
addressCheck(addressInfo($u,$at)['mode']==='formal','No group defaults to formal');
$one=addressGroup($uid,'First');query('DELETE FROM group_preferences WHERE group_id=?',[$one]);addressCheck(addressInfo($u,$at)['mode']==='formal','Legacy group without preference defaults to formal');
saveGroupAddress($one,'informal');addressCheck(addressInfo($u,$at)['mode']==='informal','Single group selects its preference');addressCheck(addressInfo($u,$at)['group_id']===$one,'Unique group is identified');addressCheck(safeUser($u)['groups'][0]['address_mode']==='informal','Safe user exposes own group preference');
$two=addressGroup($uid,'Second');$mixed=addressInfo($u,$at);addressCheck($mixed['mode']==='formal'&&$mixed['conflict'],'Conflicting accessible groups use formal');
saveGroupPeriods($one,groupPeriodsInput(['course_start'=>'2026-11-01','course_end'=>'2026-11-07']));$active=addressInfo($u,$at);addressCheck($active['mode']==='informal'&&$active['group_id']===$one&&$active['source']==='course','Current course wins over unrelated accessible membership');
$boundary=groupDateTimestamp('2026-11-07',true);addressCheck($active['next_transition']===$boundary,'Course end schedules following local midnight');addressCheck(addressInfo($u,$boundary-1)['mode']==='informal','Course end day is fully included');
saveGroupPeriods($two,groupPeriodsInput(['course_start'=>'2026-11-08','course_end'=>'2026-11-10']));addressCheck(addressInfo($u,$at)['mode']==='informal','Future course does not override current course');$next=addressInfo($u,$boundary);addressCheck($next['mode']==='formal'&&$next['group_id']===$two&&$next['source']==='course','At midnight the next current course takes over');
saveGroupPeriods($two,groupPeriodsInput(['course_start'=>'2026-11-07','course_end'=>'2026-11-09']));addressCheck(addressInfo($u,$at)['conflict'],'Overlapping courses with different preferences are explicit conflicts');saveGroupAddress($two,'informal');addressCheck(addressInfo($u,$at)['mode']==='informal'&&!addressInfo($u,$at)['conflict'],'Matching overlapping course preferences remain unambiguous');
saveGroupAddress($two,'formal');saveGroupPeriods($one,groupPeriodsInput(['access_end'=>'2026-11-06','course_start'=>'2026-11-01','course_end'=>'2026-11-06']));addressCheck(addressInfo($u,$at)['group_id']===$two,'Expired access cannot select address mode');
saveGroupPeriods($one,groupPeriodsInput(['access_start'=>'2026-11-08']));addressCheck(addressInfo($u,$at)['group_id']===$two,'Future access cannot select address mode');
query('DELETE FROM group_members WHERE user_id=? AND group_id=?',[$uid,$two]);addressCheck(addressInfo($u,$at)['mode']==='formal'&&addressInfo($u,$at)['source']==='default','No accessible groups falls back to formal');
$dst=addressGroup($uid,'DST','informal',['course_start'=>'2026-03-29','course_end'=>'2026-03-29']);$start=groupDateTimestamp('2026-03-29');$end=groupDateTimestamp('2026-03-29',true);addressCheck($end-$start===23*3600,'DST course day is 23 hours');addressCheck(addressInfo($u,$start)['group_id']===$dst&&addressInfo($u,$end-1)['mode']==='informal','DST local day boundaries select current course');
foreach([null,true,1,[],new stdClass(),'du','FORMAL','',str_repeat('x',200)] as $invalid){try{groupAddressInput($invalid);throw new RuntimeException('Invalid mode accepted');}catch(ApiError $error){addressCheck($error->status===422,'Strict address enumeration');}}
foreach(json_decode(file_get_contents(__DIR__.'/../app/address-copy.json'),true) as $entry){if(empty($entry['error']))continue;foreach(['formal','informal'] as $mode)foreach([$entry['formal'],$entry['informal']] as $source)addressCheck(addressError($source,$mode)===$entry[$mode],'Authored API error is localized');}
$opaque='Ihr Profil · Dein Projekt';addressCheck(addressError('Bitte prüfen Sie das Feld „'.$opaque.'“.','informal')==='Bitte prüfe das Feld „'.$opaque.'“.','Dynamic error field text remains opaque');addressCheck(addressError('Provider: '.$opaque,'informal')==='Provider: '.$opaque,'Unknown provider errors are untouched');
query('DELETE FROM groups WHERE id=?',[$dst]);addressCheck(!one('SELECT * FROM group_preferences WHERE group_id=?',[$dst]),'Group deletion cascades to preference');addressCheck(!db()->query('PRAGMA foreign_key_check')->fetch(),'Preference foreign keys remain consistent');
echo "$checks address, current course, conflict, calendar, validation and error checks passed.\n";
